import random, time
MOD=998244353
def solve(N,X,Y):
    Yx=[0]*(N+2)
    for i in range(1,N+1): Yx[X[i]]=Y[i]
    def ok(seq):
        n=len(seq)
        if n==0: return True
        pm=[0]*n; c=10**9
        for i in range(n):
            pm[i]=c
            if seq[i]<c: c=seq[i]
        sm=[0]*n; c=-1
        for i in range(n-1,-1,-1):
            sm[i]=c
            if seq[i]>c: c=seq[i]
        for i in range(n):
            if pm[i]>seq[i] and sm[i]<seq[i]: return False
        return True
    ans=1 if ok([Yx[x] for x in range(1,N+1)]) else 0
    dp=[0]*(N+2)
    for b in range(1,N+1):
        yb=Yx[b]
        val=1 if ok([Yx[x] for x in range(1,b) if Yx[x]>yb]) else 0
        for a in range(1,b):
            ya=Yx[a]
            if ya>yb and dp[a]:
                seq=[Yx[x] for x in range(a+1,b) if yb<Yx[x]<ya]
                if ok(seq): val+=dp[a]
        dp[b]=val%MOD
        if ok([Yx[x] for x in range(b+1,N+1) if Yx[x]<yb]): ans+=dp[b]
    return ans%MOD

def brute(N,X,Y):
    full=(1<<N)-1
    seen={full}; st=[full]
    while st:
        S=st.pop()
        bits=[i for i in range(N) if S>>i&1]
        for k in bits:
            new=1<<k
            for i in bits:
                if i==k: continue
                if not ((X[i]<X[k] and Y[i]<Y[k]) or (X[i]>X[k] and Y[i]>Y[k])):
                    new|=1<<i
            if new not in seen:
                seen.add(new); st.append(new)
    return len(seen)

