import math
def brute(n, A, B):
    def splits(a):
        return [(P,a//P) for P in range(1,a+1) if a%P==0 and math.gcd(P,a//P)==1]
    total=0
    def dfs(seq,i):
        nonlocal total
        if i==n-1:
            if math.gcd(*seq)==1:
                pr=1
                for v in seq: pr*=v
                total+=pr
            return
        s=seq[-1]
        for P,Q in splits(A[i]):
            if (s*Q)%P==0:
                t=s*Q//P
                if t<=B: dfs(seq+[t],i+1)
    for s1 in range(1,B+1): dfs([s1],0)
    return total%998244353
