import sys
import numpy as np
def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); A=list(map(int,data[1:1+n]))
    P=998244353
    M=max(A)
    phi=list(range(M+1))
    for i in range(2,M+1):
        if phi[i]==i:
            for j in range(i,M+1,i):
                phi[j]-=phi[j]//i
    phi_np=np.array(phi,dtype=np.int64)
    divs=[[] for _ in range(M+1)]
    need=set(A)
    for d in range(1,M+1):
        for k in range(d,M+1,d):
            if k in need: divs[k].append(d)
    cache={}
    C=np.zeros(M+1,dtype=np.int64)
    out=[]
    S=0
    w=1  # 2^{i-1}
    for i in range(n):
        v=A[i]
        if v in cache:
            D,PH=cache[v]
        else:
            D=np.array(divs[v],dtype=np.int64); PH=phi_np[D]
            cache[v]=(D,PH)
        T=int(np.dot(PH,C[D]))%P
        S=(2*S+T)%P
        out.append(S)
        C[D]=(C[D]+w)%P
        w=w*2%P
    sys.stdout.write("\n".join(map(str,out))+"\n")
main()

