        m = len(conflictingPairs)
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            lo, hi = (a, b) if a < b else (b, a)
            buckets[hi].append((lo, i))
        bonus = [0] * m
        base = 0
        b1v, b1i, b2v = 0, -1, 0
        for r in range(1, n + 1):
            for lo, i in buckets[r]:
                if lo > b1v:
                    b2v = b1v
                    b1v, b1i = lo, i
                elif lo > b2v:
                    b2v = lo
            base += r - b1v
            if b1i >= 0:
                bonus[b1i] += b1v - b2v
        return base + max(bonus)

