import sys
import numpy as np
def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    N = int(data[0]); M = int(data[1]); Q = int(data[2]); pos = 3
    INF = 10**18
    edges = []
    for _ in range(M):
        a = int(data[pos]) - 1; b = int(data[pos+1]) - 1; c = int(data[pos+2]); pos += 3
        edges.append((a, b, c))
    queries = []
    for _ in range(Q):
        t = int(data[pos])
        if t == 1:
            queries.append((1, int(data[pos+1]) - 1, 0))
            pos += 2
        else:
            queries.append((2, int(data[pos+1]) - 1, int(data[pos+2]) - 1))
            pos += 3
    closed = [False] * M
    for t, x, y in queries:
        if t == 1:
            closed[x] = True
    d = np.full((N, N), INF, dtype=np.int64)
    np.fill_diagonal(d, 0)
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            if c < d[a, b]:
                d[a, b] = c
                d[b, a] = c
    for k in range(N):
        d = np.minimum(d, d[:, k, None] + d[None, k, :])
    answers = []
    for t, x, y in reversed(queries):
        if t == 1:
            a, b, c = edges[x]
            d = np.minimum(d, np.minimum(d[:, a, None] + c + d[None, b, :],
                                         d[:, b, None] + c + d[None, a, :]))
        else:
            v = int(d[x, y])
            answers.append(v if v < INF else -1)
    answers.reverse()
    sys.stdout.write("\n".join(map(str, answers)) + ("\n" if answers else ""))
main()

