def brute(H,W,X,P,Q,S):
    # exhaustive closure over absorbed sets via DFS on states (set of absorbed cells)
    best=[0]
    start=frozenset([(P,Q)])
    seen={start}
    stack=[start]
    def total(st): return sum(S[i][j] for i,j in st)
    while stack:
        st=stack.pop()
        t=total(st)
        best[0]=max(best[0],t)
        for (i,j) in st:
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
