class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        nxt = {1:2, 2:0, 0:2}
        G = []
        for di, dj in dirs:
            g = [[0]*m for _ in range(n)]
            rows = range(n) if di == 1 else range(n-1, -1, -1)
            cols = range(m) if dj == 1 else range(m-1, -1, -1)
            for i in rows:
                pi = i - di
                gi = g[i]
                for j in cols:
                    v = grid[i][j]
                    if v == 1:
                        gi[j] = 1
                    else:
                        pj = j - dj
                        if 0 <= pi < n and 0 <= pj < m:
                            gp = g[pi][pj]
                            if gp and v == nxt[grid[pi][pj]]:
                                gi[j] = gp + 1
            G.append(g)
        L = []
        for k, (di, dj) in enumerate(dirs):
            ls = [[[0]*m for _ in range(n)] for _ in range(2)]
            rows = range(n-1, -1, -1) if di == 1 else range(n)
            cols = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in rows:
                ni = i + di
                for j in cols:
                    nj = j + dj
                    inb = 0 <= ni < n and 0 <= nj < m
                    v = grid[i][j]
                    for s in (0, 1):
                        e = 2 if s == 0 else 0
                        if v == e:
                            nv = ls[1-s][ni][nj] if inb else 0
                            ls[s][i][j] = 1 + nv
            L.append(ls)
        best = 0
        for k in range(4):
            g = G[k]
            k2 = (k+1) % 4
            di2, dj2 = dirs[k2]
            l2 = L[k2]
            for i in range(n):
                for j in range(m):
                    gv = g[i][j]
                    if gv == 0:
                        continue
                    if gv > best:
                        best = gv
                    qi = i + di2; qj = j + dj2
                    if 0 <= qi < n and 0 <= qj < m:
                        s = (gv - 1) % 2
                        c = gv + l2[s][qi][qj]
                        if c > best:
                            best = c
        return best

