class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            for d in range(9, 0, -1):
                if d % k == 0:
                    return str(d)
            return ""
        m = n // 2
        odd = n % 2
        full = (1 << k) - 1
        def rot(mask, w):
            w %= k
            return ((mask << w) | (mask >> (k - w))) & full if w else mask
        if odd:
            c = pow(10, m, k)
            base = 0
            for d in range(10):
                base |= 1 << ((c * d) % k)
        else:
            base = 1
        masks = [0] * (m + 1)
        masks[m] = base
        cache = {}
        pw = [pow(10, i, k) for i in range(n)]
        for j in range(m - 1, -1, -1):
            w = (pw[n - 1 - j] + pw[j]) % k
            key = (w, masks[j + 1])
            if key in cache:
                masks[j] = cache[key]
            else:
                res = 0
                for d in range(10):
                    res |= rot(masks[j + 1], w * d)
                cache[key] = res
                masks[j] = res
        digits = [0] * n
        r = 0
        for j in range(m):
            w = (pw[n - 1 - j] + pw[j]) % k
            rng = range(9, 0, -1) if j == 0 else range(9, -1, -1)
            chosen = None
            for d in rng:
                nr = (r + w * d) % k
                t = (-nr) % k
                if (masks[j + 1] >> t) & 1:
                    chosen = d
                    break
            if chosen is None:
                return ""
            r = (r + w * chosen) % k
            digits[j] = chosen
            digits[n - 1 - j] = chosen
        if odd:
            c = pow(10, m, k)
            for d in range(9, -1, -1):
                if (r + c * d) % k == 0:
                    digits[m] = d
                    break
        return "".join(map(str, digits))

