from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        a = nums
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]
        g = [n] * n
        st = []
        for i in range(n):
            while st and a[st[-1]] < a[i]:
                g[st.pop()] = i
            st.append(i)
        LOG = max(1, n.bit_length())
        W = [a[j] * (g[j] - j) - (P[g[j]] - P[j]) for j in range(n)] + [0]
        up = [g + [n]]
        SW = [W]
        for _ in range(1, LOG):
            pu = up[-1]
            ps = SW[-1]
            up.append([pu[pu[j]] for j in range(n + 1)])
            SW.append([ps[j] + ps[pu[j]] for j in range(n + 1)])
        rng = list(range(LOG - 1, -1, -1))

        def cost(l, r):
            j = l
            acc = 0
            for kk in rng:
                nj = up[kk][j]
                if nj <= r:
                    acc += SW[kk][j]
                    j = nj
            return acc + a[j] * (r - j + 1) - (P[r + 1] - P[j])

        r = -1
        ans = 0
        for l in range(n):
            if r < l - 1:
                r = l - 1
            while r + 1 < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l + 1
        return ans

