import sys

def solve(n, a):
    order = sorted(range(n), key=lambda i: a[i])
    rank = [0]*n
    for r, i in enumerate(order):
        rank[i] = r+1
    LOG = 1
    while LOG*2 <= n:
        LOG *= 2
    def pref(seq):
        cnt = [0]*(n+1); sm = [0]*(n+1)
        res = [0]*(n+1); tot = 0
        for t, i in enumerate(seq):
            p = rank[i]; v = a[i]; tot += v
            while p <= n:
                cnt[p] += 1; sm[p] += v; p += p & -p
            L = t+1
            if L % 2 == 0:
                m = L//2
                pos = 0; rem = m; acc = 0; step = LOG
                while step:
                    np_ = pos+step
                    if np_ <= n and cnt[np_] <= rem:
                        pos = np_; rem -= cnt[np_]; acc += sm[np_]
                    step >>= 1
                res[L] = tot - 2*acc
        return res
    pre = pref(list(range(n)))
    if n % 2 == 0:
        return pre[n]
    suf = pref(list(range(n-1, -1, -1)))
    best = None
    for i in range(0, n, 2):
        val = pre[i] + suf[n-1-i]
        if best is None or val > best:
