class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)
        def occ(pat):
            L = len(pat)
            if L == 0:
                return list(range(n + 1))
            t = pat + '#' + s
            pi = [0] * len(t)
            for i in range(1, len(t)):
                k = pi[i-1]
                while k and t[i] != t[k]:
                    k = pi[k-1]
                if t[i] == t[k]:
                    k += 1
                pi[i] = k
            res = []
            for i in range(L + 1, len(t)):
                if pi[i] == L:
                    res.append(i - 2 * L)
            return res
        oa, ob, oc = occ(a), occ(b), occ(c)
        if not oa or not ob or not oc:
            return -1
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for k in ob:
            idx = bisect.bisect_right(oa, k - la) - 1
            if idx < 0:
                continue
            i = oa[idx]
            j = bisect.bisect_left(oc, k + lb)
            if j >= len(oc):
                continue
            m = oc[j]
            L = m + lc - i
            if best < 0 or L < best:
