from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        order = []
        stack = [(0, 0)]
        while stack:
            x, k = stack.pop()
            if k < len(children[x]):
                stack.append((x, k + 1))
                stack.append((children[x][k], 0))
            else:
                order.append(x)
        pos = [0] * n
        for idx, x in enumerate(order):
            pos[x] = idx
        size = [1] * n
        for x in order:
            if x != 0:
                size[parent[x]] += size[x]
        T = ''.join(s[x] for x in order)
        t = '#' + '#'.join(T) + '#'
        m = len(t)
        p = [0] * m
        C = R = 0
        for i in range(m):
            if i < R:
                p[i] = min(R - i, p[2 * C - i])
            while i - p[i] - 1 >= 0 and i + p[i] + 1 < m and t[i - p[i] - 1] == t[i + p[i] + 1]:
                p[i] += 1
            if i + p[i] > R:
                C = i
                R = i + p[i]
        ans = [False] * n
        for x in range(n):
            r = pos[x]
            l = r - size[x] + 1
            ans[x] = p[l + r + 1] >= r - l + 1
        return ans

