import sys, random
def fast(n, a):
    L = [0]*(n+1)
    seen = set()
    for i in range(n):
        seen.add(a[i]); L[i+1] = len(seen)
    R = [0]*(n+1)
    seen = set()
    for i in range(n-1, 0, -1):
        seen.add(a[i]); R[i] = len(seen)
    # split after i elements (1..n-1): left = a[0..i-1], right = a[i..n-1]
    return max(L[i] + R[i] for i in range(1, n))
def brute(n, a):
    best = -1
    for i in range(1, n):
        best = max(best, len(set(a[:i])) + len(set(a[i:])))
    return best
