import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        sieve = [True] * LIM
        sieve[0] = sieve[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        L = len(str(n))
        INF = float('inf')
        dist = [INF] * LIM
        dist[n] = n
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist[v]:
                continue
            if v == m:
                return d
            p = 1
            for _ in range(L):
                dig = (v // p) % 10
                for nv in ((v + p) if dig < 9 else None, (v - p) if dig > 0 else None):
                    if nv is None:
                        continue
                    if sieve[nv]:
                        continue
                    nd = d + nv
                    if nd < dist[nv]:
                        dist[nv] = nd
                        heapq.heappush(pq, (nd, nv))
                p *= 10
        return dist[m] if dist[m] < INF else -1

