class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        half = n // 2
        dp = {}
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[(a, b)] = cost[0][a] + cost[n-1][b]
        for i in range(1, half):
            nd = {}
            for a2 in range(3):
                for b2 in range(3):
                    if a2 == b2:
                        continue
                    best = INF
                    for (a, b), v in dp.items():
                        if a2 != a and b2 != b and v < best:
                            best = v
                    if best < INF:
                        nd[(a2, b2)] = best + cost[i][a2] + cost[n-1-i][b2]
            dp = nd
        return min(dp.values())

